#!/usr/bin/env node
// Copies specification documents into the Starlight content collection.
//
// Some pages on the docs site are not authored here. Their source of truth is a
// specification under specs/, which is reviewed with the code it describes. This
// script renders those sources as content-collection entries so the site can
// publish them without a second copy being edited by hand and drifting.
//
// The generated files are gitignored. They are produced by `npm run build` and
// `npm run dev` (see the prebuild/predev scripts in package.json), so a fresh
// clone builds a complete site without anyone remembering to run this.
//
// Usage:
//   node scripts/sync-content.mjs           write the generated pages
//   node scripts/sync-content.mjs --check   verify they are current; exit 1 if not

import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const docsDir = join(dirname(fileURLToPath(import.meta.url)), '..');
const repoRoot = join(docsDir, '..');

// Each entry names a specification document and the page it becomes. `title`
// and `description` are the site's, not the source's: the source opens with an
// H1 written for a standalone document, which Starlight renders from frontmatter
// instead. That H1 is dropped so the page does not carry two titles.
const PAGES = [
	{
		source: 'specs/001-cloud-native-nsm/quickstart.md',
		output: 'src/content/docs/quickstart.md',
		title: 'Quickstart',
		description:
			'The release-candidate acceptance path: install Trawl, then validate every user story against a real cluster.',
	},
];

// Strip a single leading H1 and the blank line after it. Anything else is left
// exactly as written, including the source's own heading levels.
function stripLeadingTitle(body) {
	const lines = body.split('\n');
	let i = 0;
	while (i < lines.length && lines[i].trim() === '') i += 1;
	if (i < lines.length && /^#\s+\S/.test(lines[i])) {
		i += 1;
		while (i < lines.length && lines[i].trim() === '') i += 1;
		return lines.slice(i).join('\n');
	}
	return body;
}

// A YAML double-quoted scalar. Titles and descriptions are ours rather than
// arbitrary input, but a stray quote would produce a file that fails to parse
// rather than one that looks wrong, so it is worth the three lines.
function yamlString(value) {
	return `"${value.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`;
}

function render(page, body) {
	return [
		'---',
		`title: ${yamlString(page.title)}`,
		`description: ${yamlString(page.description)}`,
		`# Generated by docs/scripts/sync-content.mjs from ${page.source}. Do not edit.`,
		'editUrl: false',
		'---',
		'',
		':::note',
		`This page is generated from \`${page.source}\`. Edit that file — changes made here are overwritten by the next build.`,
		':::',
		'',
		stripLeadingTitle(body),
	].join('\n');
}

const check = process.argv.includes('--check');
let stale = 0;

for (const page of PAGES) {
	const sourcePath = join(repoRoot, page.source);
	const outputPath = join(docsDir, page.output);

	if (!existsSync(sourcePath)) {
		console.error(
			`sync-content: ${page.source} does not exist. It is the source for ${page.output}; ` +
				'either restore it or remove the entry from PAGES in docs/scripts/sync-content.mjs.',
		);
		process.exit(1);
	}

	const rendered = render(page, readFileSync(sourcePath, 'utf8'));
	const current = existsSync(outputPath) ? readFileSync(outputPath, 'utf8') : null;

	if (current === rendered) continue;

	if (check) {
		stale += 1;
		console.error(
			`sync-content: ${relative(repoRoot, outputPath)} is out of date with ${page.source}. ` +
				'Run `npm run sync` in docs/.',
		);
		continue;
	}

	mkdirSync(dirname(outputPath), { recursive: true });
	writeFileSync(outputPath, rendered);
	console.log(`sync-content: wrote ${page.output} from ${page.source}`);
}

if (stale > 0) process.exit(1);
